def main():
    n = int(input())
    q = list(map(int, input().split()))
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    am = 10**6
    for i in range(n):
        if a[i] == 0:
            continue
        if am > q[i] // a[i]:
            am = q[i] // a[i]

    bm = 10**6
    for i in range(n):
        if b[i] == 0:
            continue
        if bm > q[i] // b[i]:
            bm = q[i] // b[i]

    ans = 0

    for i in range(am + 1):
        remaining = [q[j] - i * a[j] for j in range(n)]
        t = 0
        for j in range(n):
            if b[j] > 0:
                t += remaining[j] // b[j]
        ans = max(ans, i + t)

    print(ans)
